            title: { 'es-AR': '5. Calidez Solar en la Mirada', 'en': '5. Warm Sunbeams and Gaze' },
            caption: { 'es-AR': 'Retrato cercano iluminado por la luz dorada.', en: 'Close portrait illuminated by golden hour sun.' }
